/*
Person-held papers and government personal codes (D-Documents / D-PersonalCodes). Documents and
codes are scoped THROUGH THE HOLDER (D-PersonReadScope) + the shadow gate; type/scheme catalogs
are instance-admin-managed. Personal-code values are envelope-encrypted at rest (D-CryptoProvider)
and validated against their scheme on write. Writes are audited in-process (D-Audit).
*/
type DocumentServiceClientWithAuth interface {
	// Attach a paper to a person. Returns Document:DocumentConflict on a duplicate (type, number).
	AttachDocument(ctx context.Context, personIdArg string, requestArg CreateDocumentRequest) (Document, error)
	/*
	   List documents across every holder the caller may read, token-paginated, narrowed by the
	   document facet set (D-ObjectFacets, M56). Documents are scoped THROUGH THE HOLDER
	   (D-PersonReadScope): a non-instance-admin caller sees only documents whose holder falls in
	   their read-scope union. Every filter below is applied INSIDE that union, before the page is
	   cut, so a filtered page is never short and its cursor is never wrong.

	   Metadata only — the same projection the per-holder listing returns. The facet filters
	   combine with AND and do NOT widen what the caller may see: filtering can only narrow the
	   visible set.
	*/
	ListDocuments(ctx context.Context, pageSizeArg *int, pageTokenArg *string, typeIdArg *string, statusArg *string, issuingCountryIdArg *string, issuedOnFromArg *string, issuedOnToArg *string, expiresOnFromArg *string, expiresOnToArg *string) (DocumentPage, error)
	/*
	   Facet distributions for the document register — the dashboard half of the facet vocabulary
	   (M57 / D-ObjectFacets). Takes exactly the filter args `listDocuments` takes (minus paging), so
	   a dashboard and a list are two renderings of one request state.

	   Counted INSIDE the holder read-scope semi-join: `totalCount` equals what exhaustively paging
	   `listDocuments` with these filters would return. The `expiresOn` distribution's `(unknown)`
	   bucket is the NO-EXPIRY (permanent) population, not missing data.

	   The path is `/stats/documents` rather than `/documents/stats` because the server's router
	   rejects a literal path segment that is a sibling of `{documentId}` — see the route-conflict
	   guard in `internal/platform/transport`.
	*/
	DocumentStats(ctx context.Context, facetsArg *string, typeIdArg *string, statusArg *string, issuingCountryIdArg *string, issuedOnFromArg *string, issuedOnToArg *string, expiresOnFromArg *string, expiresOnToArg *string) (DocumentStats, error)
	// List a person's documents, token-paginated.
	ListPersonDocuments(ctx context.Context, personIdArg string, pageSizeArg *int, pageTokenArg *string) (DocumentPage, error)
	// Read one document.
	GetDocument(ctx context.Context, documentIdArg string) (Document, error)
	// Update number/issuer/issuing-country/validity/attributes/status. Omitted fields are unchanged.
	UpdateDocument(ctx context.Context, documentIdArg string, requestArg UpdateDocumentRequest) (Document, error)
	// Soft-delete (reversible) a document.
	DeleteDocument(ctx context.Context, documentIdArg string) error
	// List the paper-type catalog.
	ListDocumentTypes(ctx context.Context) ([]DocumentType, error)
	// Add a document type (instance-scope). Returns Document:DocumentTypeConflict if the code is taken.
	CreateDocumentType(ctx context.Context, requestArg CreateDocumentTypeRequest) (DocumentType, error)
	// Edit a document type (instance-scope). `code` is immutable by convention.
	UpdateDocumentType(ctx context.Context, typeIdArg string, requestArg UpdateDocumentTypeRequest) (DocumentType, error)
	/*
	   Attach a national-identifier code to a person. The value is validated against the scheme
	   (Document:PersonalCodeInvalid on failure) and encrypted; a duplicate (scheme, value) returns
	   Document:PersonalCodeDuplicate.
	*/
	AttachPersonalCode(ctx context.Context, personIdArg string, requestArg CreatePersonalCodeRequest) (PersonalCode, error)
	// List a person's personal codes (values decrypted on read; a sensitive action).
	ListPersonPersonalCodes(ctx context.Context, personIdArg string) ([]PersonalCode, error)
	// Update a personal code (value re-validated + re-encrypted, and/or status).
	UpdatePersonalCode(ctx context.Context, codeIdArg string, requestArg UpdatePersonalCodeRequest) (PersonalCode, error)
	// Soft-delete a personal code.
	DeletePersonalCode(ctx context.Context, codeIdArg string) error
	// List the scheme catalog, optionally filtered by country RID (GET /geo/countries) and/or generic category.
	ListPersonalCodeSchemes(ctx context.Context, countryArg *string, categoryArg *string) ([]PersonalCodeScheme, error)
	// Add a scheme (instance-scope). Returns Document:PersonalCodeSchemeConflict if the code is taken.
	CreatePersonalCodeScheme(ctx context.Context, requestArg CreatePersonalCodeSchemeRequest) (PersonalCodeScheme, error)
	// Edit a scheme (instance-scope). `code` is immutable by convention.
	UpdatePersonalCodeScheme(ctx context.Context, schemeCodeArg string, requestArg UpdatePersonalCodeSchemeRequest) (PersonalCodeScheme, error)
}

func NewDocumentServiceClientWithAuth(client DocumentServiceClient, authHeader bearertoken.Token) DocumentServiceClientWithAuth {
	return &documentServiceClientWithAuth{client: client, authHeader: authHeader}
}

