func NewDocumentServiceClientWithTokenProvider(client DocumentServiceClient, tokenProvider httpclient.TokenProvider) DocumentServiceClientWithAuth {
	return &documentServiceClientWithTokenProvider{client: client, tokenProvider: tokenProvider}
}

type documentServiceClientWithTokenProvider struct {
	client        DocumentServiceClient
	tokenProvider httpclient.TokenProvider
}

func (c *documentServiceClientWithTokenProvider) AttachDocument(ctx context.Context, personIdArg string, requestArg CreateDocumentRequest) (Document, error) {
	token, err := c.tokenProvider(ctx)
	if err != nil {
		return *new(Document), err
	}
	return c.client.AttachDocument(ctx, bearertoken.Token(token), personIdArg, requestArg)
}

